export default {"f-card-c8a-teach":{"kind":"lesson","src":"card:c8a#teach","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"Revenue is what came in. Cost is what you paid to make it happen. Profit is what's left. A busy shop with no profit is a tiring hobby.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","card":"c8a","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-teach","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-eg":{"kind":"example","src":"card:c8a#eg","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"40 umbrellas at 20 = 800 in. They cost 8 each = 320 out. Profit 480.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-eg","bands":["sprout","builder"],"grp":"card:c8a"},"f-lesson-c8a-beats0-1":{"kind":"line","src":"lesson:c8a#beats0-1","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"Revenue. Cost. Profit. Three words shopkeepers refuse to mix up.\nRevenue is everything that came in. Forty umbrellas at twenty each — eight hundred in.","route":"#/atlas/c8a","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-lesson-c8a-beats0-1","bands":["sprout","builder"],"grp":"card:c8a"},"f-lesson-c8a-beat2":{"kind":"line","src":"lesson:c8a#beat2","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"Cost is what you paid to make that happen. The umbrellas cost eight each — three hundred and twenty out.","route":"#/atlas/c8a","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-lesson-c8a-beat2","bands":["sprout","builder"],"grp":"card:c8a"},"f-lesson-c8a-beats3-4":{"kind":"line","src":"lesson:c8a#beats3-4","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"Profit is what is left. Four hundred and eighty.\nA busy shop with no profit is not a business. It is a very tiring hobby.","route":"#/atlas/c8a","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-lesson-c8a-beats3-4","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-q0":{"kind":"question","src":"card:c8a#q0","level":8,"topics":["card:c8a","ch:c8","who:nana"],"key":"c8a#0","title":"Three different words","play":{"q":"A stall takes 1,000 and spent 900 on stock. What is the profit?","opts":["100","1,900","1,000","900"],"after":"Revenue is the number people brag about. Profit decides if you're open next year."},"route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-q0","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-q1":{"kind":"question","src":"card:c8a#q1","level":8,"topics":["card:c8a","ch:c8","who:nana"],"key":"c8a#1","title":"Three different words","play":{"q":"800 came in, the stock cost 320. The 480 is…","opts":["Profit","Cost","Cash flow","Revenue"],"after":"Revenue in, cost out, profit is what is left. Three words, never mixed."},"route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-q1","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-q2":{"kind":"question","src":"card:c8a#q2","level":8,"topics":["card:c8a","ch:c8","who:nana"],"key":"c8a#2","title":"Three different words","play":{"q":"A shop is packed all day but profit is zero. What is it?","opts":["A very tiring hobby","A thriving business","About to be rich","Impossible to happen"],"after":"Busy is revenue’s friend, not profit’s. No leftover, no business."},"route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-q2","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-why0":{"kind":"why","src":"card:c8a#why0","level":8,"topics":["card:c8a","ch:c8","who:nana"],"card":"c8a","title":"Three different words","body":"Revenue is the number people brag about. Profit decides if you're open next year.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-why0","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-why1":{"kind":"why","src":"card:c8a#why1","level":8,"topics":["card:c8a","ch:c8","who:nana"],"card":"c8a","title":"Three different words","body":"Revenue in, cost out, profit is what is left. Three words, never mixed.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-why1","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8a-why2":{"kind":"why","src":"card:c8a#why2","level":8,"topics":["card:c8a","ch:c8","who:nana"],"card":"c8a","title":"Three different words","body":"Busy is revenue’s friend, not profit’s. No leftover, no business.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8a-why2","bands":["sprout","builder"],"grp":"card:c8a"},"f-tryit-c8a":{"kind":"tryit","src":"tryit:c8a","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Try it","body":"Revenue, cost, profit","route":"#/atlas/c8a","cta":"Change the numbers","maths":"M8","source":"Chapter 8 · Running something · Three different words · with Nana Bizz","id":"f-tryit-c8a","bands":["sprout","builder"],"grp":"card:c8a"},"f-card-c8b-teach":{"kind":"lesson","src":"card:c8b#teach","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Setting a price","body":"Too cheap and you sell out but earn nothing. Too dear and you carry it home. The right price is the most people will happily pay — find it by trying.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","card":"c8b","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-teach","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-eg":{"kind":"example","src":"card:c8b#eg","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Setting a price","body":"Mags raised buttons from 8 to 12 and sold two fewer. She made more and went home early.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-eg","bands":["sprout","builder"],"grp":"card:c8b"},"f-lesson-c8b-beats1-2":{"kind":"line","src":"lesson:c8b#beats1-2","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Setting a price","body":"Price too high, and you carry the stock home again.\nThe right price is not 'cost plus a bit'. It is the most people will happily pay.","route":"#/atlas/c8b","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-lesson-c8b-beats1-2","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-q0":{"kind":"question","src":"card:c8b#q0","level":8,"topics":["card:c8b","ch:c8","who:mags"],"key":"c8b#0","title":"Setting a price","play":{"q":"You raise the price and sell a few less, but take more money overall. What should you do?","opts":["Keep the new price","Halve the price","Go back to the old price","Stop selling them"],"after":"What counts is total profit, not how many you sold."},"route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-q0","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-q1":{"kind":"question","src":"card:c8b#q1","level":8,"topics":["card:c8b","ch:c8","who:mags"],"key":"c8b#1","title":"Setting a price","play":{"q":"Mags raised buttons from 8 to 12 and sold two fewer. Result?","opts":["More money, home earlier","She lost her customers","Less money overall","Exactly the same takings"],"after":"Fewer sales at a better price beat more sales at a poor one — you find this only by trying."},"route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-q1","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-q2":{"kind":"question","src":"card:c8b#q2","level":8,"topics":["card:c8b","ch:c8","who:mags"],"key":"c8b#2","title":"Setting a price","play":{"q":"You price so low you sell out by lunch. What did the card call that?","opts":["Earning nothing while busy","A triumph of marketing","The scientific method","Perfect stock control"],"after":"Sold out fast usually means priced too low: all the work, none of the profit."},"route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-q2","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-why0":{"kind":"why","src":"card:c8b#why0","level":8,"topics":["card:c8b","ch:c8","who:mags"],"card":"c8b","title":"Setting a price","body":"What counts is total profit, not how many you sold.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-why0","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-why1":{"kind":"why","src":"card:c8b#why1","level":8,"topics":["card:c8b","ch:c8","who:mags"],"card":"c8b","title":"Setting a price","body":"Fewer sales at a better price beat more sales at a poor one — you find this only by trying.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-why1","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8b-why2":{"kind":"why","src":"card:c8b#why2","level":8,"topics":["card:c8b","ch:c8","who:mags"],"card":"c8b","title":"Setting a price","body":"Sold out fast usually means priced too low: all the work, none of the profit.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8b-why2","bands":["sprout","builder"],"grp":"card:c8b"},"f-item-c8b":{"kind":"yourturn","src":"item:c8b","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Your turn","body":"Fewer sold, more taken\nWork out each week’s takings — how many sold times the price — then find the gap.","route":"#/atlas/c8b","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Setting a price · with Mags","id":"f-item-c8b","bands":["sprout","builder"],"grp":"card:c8b"},"f-card-c8j-teach":{"kind":"lesson","src":"card:c8j#teach","level":8,"topics":["card:c8j","ch:c8","who:mags"],"title":"Try a small batch first","body":"Before you make a hundred of something, make a few. Sell them, watch what happens, change what did not work, then make more. A small test costs little. A big mistake costs a lot.","route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","card":"c8j","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-teach","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-eg":{"kind":"example","src":"card:c8j#eg","level":8,"topics":["card:c8j","ch:c8","who:mags"],"title":"Try a small batch first","body":"Mags made 5 painted umbrellas, not 50. The blue ones sold in a day; the yellow ones sat. Her next batch was mostly blue.","route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-eg","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-q0":{"kind":"question","src":"card:c8j#q0","level":8,"topics":["card:c8j","ch:c8","who:mags"],"key":"c8j#0","title":"Try a small batch first","play":{"q":"You have an idea for a new thing to sell. What is the wisest first step?","opts":["Make a few and see if they sell","Make as many as you can afford","Wait until it is perfect","Borrow to make a big batch"],"after":"A few tell you what people want before much money is stuck on a shelf."},"route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-q0","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-q1":{"kind":"question","src":"card:c8j#q1","level":8,"topics":["card:c8j","ch:c8","who:mags"],"key":"c8j#1","title":"Try a small batch first","play":{"q":"Mags’s yellow umbrellas did not sell. What did the small test save her?","opts":["Money she would have stuck in yellow stock","The cost of the blue paint","Her rent for the month","Nothing, it was a waste"],"after":"Finding out with five is cheap. Finding out with fifty is stock that sits."},"route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-q1","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-q2":{"kind":"question","src":"card:c8j#q2","level":8,"topics":["card:c8j","ch:c8","who:mags"],"key":"c8j#2","title":"Try a small batch first","play":{"q":"A small batch sold well. What comes next?","opts":["Make more, keeping what worked","Change everything about it","Stop, it worked once","Double the price at once"],"after":"Test, learn, then grow — and keep testing as you go."},"route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-q2","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-why0":{"kind":"why","src":"card:c8j#why0","level":8,"topics":["card:c8j","ch:c8","who:mags"],"card":"c8j","title":"Try a small batch first","body":"A few tell you what people want before much money is stuck on a shelf.","route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-why0","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-why1":{"kind":"why","src":"card:c8j#why1","level":8,"topics":["card:c8j","ch:c8","who:mags"],"card":"c8j","title":"Try a small batch first","body":"Finding out with five is cheap. Finding out with fifty is stock that sits.","route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-why1","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8j-why2":{"kind":"why","src":"card:c8j#why2","level":8,"topics":["card:c8j","ch:c8","who:mags"],"card":"c8j","title":"Try a small batch first","body":"Test, learn, then grow — and keep testing as you go.","route":"#/atlas/c8j","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8j-why2","bands":["sprout","builder"],"grp":"card:c8j"},"f-item-c8j":{"kind":"yourturn","src":"item:c8j","level":8,"topics":["card:c8j","ch:c8","who:mags"],"title":"Your turn","body":"Testing an idea\nSmall and cheap comes before big. Learn before you grow.","route":"#/atlas/c8j","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Try a small batch first · with Mags","id":"f-item-c8j","bands":["sprout","builder"],"grp":"card:c8j"},"f-card-c8c-teach":{"kind":"lesson","src":"card:c8c#teach","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Cash is not profit","body":"You can be profitable and broke at the same time. Profit is a month on paper. Cash is what's in your hand when the stock bill is due.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","card":"c8c","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-teach","bands":["builder"],"grp":"card:c8c"},"f-card-c8c-eg":{"kind":"example","src":"card:c8c#eg","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Cash is not profit","body":"Nana's best month nearly closed the shop: the restock bill came before the sales did.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-eg","bands":["sprout","builder"],"grp":"card:c8c"},"f-lesson-c8c-beats0-1":{"kind":"line","src":"lesson:c8c#beats0-1","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Cash is not profit","body":"Here is the strangest true thing in this whole chapter: you can be profitable and broke at the same time.\nProfit lives on paper, over a month.","route":"#/atlas/c8c","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-lesson-c8c-beats0-1","bands":["sprout","builder"],"grp":"card:c8c"},"f-lesson-c8c-beat2":{"kind":"line","src":"lesson:c8c#beat2","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Cash is not profit","body":"Cash is what is actually in your hand on Tuesday — when the stock must be paid for and the customers have not come yet.","route":"#/atlas/c8c","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-lesson-c8c-beat2","bands":["sprout","builder"],"grp":"card:c8c"},"f-lesson-c8c-beats3-4":{"kind":"line","src":"lesson:c8c#beats3-4","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Cash is not profit","body":"My best-ever month nearly closed the shop. The restock was due before the sales landed.\nWatch the paper once a month. Watch your hand every day.","route":"#/atlas/c8c","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-lesson-c8c-beats3-4","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-q0":{"kind":"question","src":"card:c8c#q0","level":8,"topics":["card:c8c","ch:c8","who:pip"],"key":"c8c#0","title":"Cash is not profit","play":{"q":"Your shop is profitable but you cannot pay for stock this week. What is the problem?","opts":["Money comes in later than it goes out","You sold too much","The price is wrong","You are not profitable really"],"after":"Timing closes more small shops than pricing. Cash is a fact about today."},"route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-q0","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-q1":{"kind":"question","src":"card:c8c#q1","level":8,"topics":["card:c8c","ch:c8","who:pip"],"key":"c8c#1","title":"Cash is not profit","play":{"q":"Profitable on paper, no cash on Tuesday. What happened?","opts":["Bills came before the sales landed","It cannot happen","Profit was stolen","The bookkeeping is wrong"],"after":"Nana’s best month nearly closed the shop: the restock was due first. Timing is the trap."},"route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-q1","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-q2":{"kind":"question","src":"card:c8c#q2","level":8,"topics":["card:c8c","ch:c8","who:pip"],"key":"c8c#2","title":"Cash is not profit","play":{"q":"How often do you watch cash versus profit?","opts":["Cash daily, paper monthly","Both monthly is fine","Profit daily, cash monthly","Only at year end"],"after":"Profit is a monthly story. Cash is a Tuesday-morning fact."},"route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-q2","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-why0":{"kind":"why","src":"card:c8c#why0","level":8,"topics":["card:c8c","ch:c8","who:pip"],"card":"c8c","title":"Cash is not profit","body":"Timing closes more small shops than pricing. Cash is a fact about today.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-why0","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-why1":{"kind":"why","src":"card:c8c#why1","level":8,"topics":["card:c8c","ch:c8","who:pip"],"card":"c8c","title":"Cash is not profit","body":"Nana’s best month nearly closed the shop: the restock was due first. Timing is the trap.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-why1","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8c-why2":{"kind":"why","src":"card:c8c#why2","level":8,"topics":["card:c8c","ch:c8","who:pip"],"card":"c8c","title":"Cash is not profit","body":"Profit is a monthly story. Cash is a Tuesday-morning fact.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Pip","id":"f-card-c8c-why2","bands":["sprout","builder"],"grp":"card:c8c"},"f-item-c8c":{"kind":"yourturn","src":"item:c8c","level":8,"topics":["card:c8c","ch:c8","who:pip"],"title":"Your turn","body":"A shop’s month\nThe bills often come before the sales do. That is why cash is not profit.","route":"#/atlas/c8c","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Cash is not profit · with Pip","id":"f-item-c8c","bands":["sprout","builder"],"grp":"card:c8c"},"f-card-c8d-teach":{"kind":"lesson","src":"card:c8d#teach","level":8,"topics":["card:c8d","ch:c8","who:nana"],"title":"The stuff that arrives anyway","body":"Rent arrives whether you sell or not — that's fixed. Stock costs come only when you sell — that's variable. Quiet weeks hurt because fixed costs don't care.","route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","card":"c8d","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-teach","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-eg":{"kind":"example","src":"card:c8d#eg","level":8,"topics":["card:c8d","ch:c8","who:nana"],"title":"The stuff that arrives anyway","body":"200 rent a month is about seven a day, before you sell a thing.","route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-eg","bands":["sprout","builder"],"grp":"card:c8d"},"f-lesson-c8d-beats0-1":{"kind":"line","src":"lesson:c8d#beats0-1","level":8,"topics":["card:c8d","ch:c8","who:nana"],"title":"The stuff that arrives anyway","body":"Some costs arrive whether you sold anything or not. Rent. Licences. Those are fixed.\nSome costs only arrive when you sell. Stock. Those are variable.","route":"#/atlas/c8d","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-lesson-c8d-beats0-1","bands":["sprout","builder"],"grp":"card:c8d"},"f-lesson-c8d-beats2-4":{"kind":"line","src":"lesson:c8d#beats2-4","level":8,"topics":["card:c8d","ch:c8","who:nana"],"title":"The stuff that arrives anyway","body":"A quiet week hurts because the fixed ones do not care that it was quiet.\nTwo hundred rent a month is seven a day — before you have sold a single thing.\nKnow your seven. Every shopkeeper who lasts does.","route":"#/atlas/c8d","cta":"Watch the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-lesson-c8d-beats2-4","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-q0":{"kind":"question","src":"card:c8d#q0","level":8,"topics":["card:c8d","ch:c8","who:nana"],"key":"c8d#0","title":"The stuff that arrives anyway","play":{"q":"Which cost still arrives in a week you sell nothing?","opts":["Rent","Nothing does","Wrapping paper","Stock"],"after":"Your fixed costs tell you the smallest week you can survive."},"route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-q0","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-q1":{"kind":"question","src":"card:c8d#q1","level":8,"topics":["card:c8d","ch:c8","who:nana"],"key":"c8d#1","title":"The stuff that arrives anyway","play":{"q":"Which cost arrives even in a week where you sell nothing?","opts":["The rent","The wrapping paper","The delivery fee","The stock"],"after":"Fixed costs do not care that it was quiet. That is exactly why quiet weeks hurt."},"route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-q1","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-q2":{"kind":"question","src":"card:c8d#q2","level":8,"topics":["card:c8d","ch:c8","who:nana"],"key":"c8d#2","title":"The stuff that arrives anyway","play":{"q":"200 rent a month is \"seven a day\". Why does a shopkeeper carry that number?","opts":["It is what breaking even starts at","The landlord quotes it so","Rent is paid daily in town","Sevens are easy to recall"],"after":"Before the first sale, the day is already seven down. Knowing your seven is knowing your floor."},"route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-q2","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-why0":{"kind":"why","src":"card:c8d#why0","level":8,"topics":["card:c8d","ch:c8","who:nana"],"card":"c8d","title":"The stuff that arrives anyway","body":"Your fixed costs tell you the smallest week you can survive.","route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-why0","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-why1":{"kind":"why","src":"card:c8d#why1","level":8,"topics":["card:c8d","ch:c8","who:nana"],"card":"c8d","title":"The stuff that arrives anyway","body":"Fixed costs do not care that it was quiet. That is exactly why quiet weeks hurt.","route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-why1","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8d-why2":{"kind":"why","src":"card:c8d#why2","level":8,"topics":["card:c8d","ch:c8","who:nana"],"card":"c8d","title":"The stuff that arrives anyway","body":"Before the first sale, the day is already seven down. Knowing your seven is knowing your floor.","route":"#/atlas/c8d","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8d-why2","bands":["sprout","builder"],"grp":"card:c8d"},"f-item-c8d":{"kind":"yourturn","src":"item:c8d","level":8,"topics":["card:c8d","ch:c8","who:nana"],"title":"Your turn","body":"Arrives anyway, or only with a sale?\nAsk: in a week where nothing sells, does this still arrive?","route":"#/atlas/c8d","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · The stuff that arrives anyway · with Nana Bizz","id":"f-item-c8d","bands":["sprout","builder"],"grp":"card:c8d"},"f-card-c8i-teach":{"kind":"lesson","src":"card:c8i#teach","level":8,"topics":["card:c8i","ch:c8","who:nana"],"title":"Your time is a cost too","body":"Profit after materials is not the whole story. Your own hours went in too. Share the profit across the hours and you see what each hour really earned. Then compare it with a job.","route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","card":"c8i","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-teach","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-eg":{"kind":"example","src":"card:c8i#eg","level":8,"topics":["card:c8i","ch:c8","who:nana"],"title":"Your time is a cost too","body":"Pip sold 10 bracelets at 9, and the beads cost 3 each. Profit 60, after 5 hours: 60 ÷ 5 = 12 an hour.","route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-eg","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-q0":{"kind":"question","src":"card:c8i#q0","level":8,"topics":["card:c8i","ch:c8","who:nana"],"key":"c8i#0","title":"Your time is a cost too","play":{"q":"Two stalls each make 60 profit. One took 3 hours, the other 10. Which earned more for each hour?","opts":["The one that took 3 hours","The one that took 10 hours","They earned the same","You cannot tell"],"after":"60 ÷ 3 = 20 an hour against 60 ÷ 10 = 6. Same profit, very different hours."},"route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-q0","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-q1":{"kind":"question","src":"card:c8i#q1","level":8,"topics":["card:c8i","ch:c8","who:nana"],"key":"c8i#1","title":"Your time is a cost too","play":{"q":"Why share a stall’s profit across the hours you worked?","opts":["To see what each hour earned","To set the price of beads","To work out the rent","To count the stock"],"after":"A figure for each hour lets you compare the stall with any other way of spending that time."},"route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-q1","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-q2":{"kind":"question","src":"card:c8i#q2","level":8,"topics":["card:c8i","ch:c8","who:nana"],"key":"c8i#2","title":"Your time is a cost too","play":{"q":"Your stall earns 4 an hour. Crate-stacking pays 6 an hour. What does that tell you?","opts":["The stall pays less an hour, so is it worth it?","The stall is always better","Stacking crates is a bad job","Nothing useful at all"],"after":"It may still be worth it: you are learning, or you enjoy it. But now you are choosing with the real number."},"route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-q2","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-why0":{"kind":"why","src":"card:c8i#why0","level":8,"topics":["card:c8i","ch:c8","who:nana"],"card":"c8i","title":"Your time is a cost too","body":"60 ÷ 3 = 20 an hour against 60 ÷ 10 = 6. Same profit, very different hours.","route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-why0","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-why1":{"kind":"why","src":"card:c8i#why1","level":8,"topics":["card:c8i","ch:c8","who:nana"],"card":"c8i","title":"Your time is a cost too","body":"A figure for each hour lets you compare the stall with any other way of spending that time.","route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-why1","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8i-why2":{"kind":"why","src":"card:c8i#why2","level":8,"topics":["card:c8i","ch:c8","who:nana"],"card":"c8i","title":"Your time is a cost too","body":"It may still be worth it: you are learning, or you enjoy it. But now you are choosing with the real number.","route":"#/atlas/c8i","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8i-why2","bands":["sprout","builder"],"grp":"card:c8i"},"f-item-c8i":{"kind":"yourturn","src":"item:c8i","level":8,"topics":["card:c8i","ch:c8","who:nana"],"title":"Your turn","body":"What each hour earned\nFind the profit first — what came in, take away the beads — then share it across the hours.","route":"#/atlas/c8i","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Your time is a cost too · with Nana Bizz","id":"f-item-c8i","bands":["sprout","builder"],"grp":"card:c8i"},"f-card-c8e-teach":{"kind":"lesson","src":"card:c8e#teach","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Break-even","body":"Before a shop makes any profit, it has to cover its fixed costs. The number of sales that does that is the break-even. Every sale after it is profit.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","card":"c8e","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-teach","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-eg":{"kind":"example","src":"card:c8e#eg","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Break-even","body":"Rent 240 a month. Each umbrella sells for 20 and costs 8, so it leaves 12. 240 ÷ 12 = 20 umbrellas to break even.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-eg","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-q0":{"kind":"question","src":"card:c8e#q0","level":8,"topics":["card:c8e","ch:c8","who:mags"],"key":"c8e#0","title":"Break-even","play":{"q":"Rent is 300 a month. Each sale leaves 15 after its own cost. How many sales to break even?","opts":["20","15","30","300"],"after":"300 ÷ 15 = 20. The twenty-first sale is the first one that is profit."},"route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-q0","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-q1":{"kind":"question","src":"card:c8e#q1","level":8,"topics":["card:c8e","ch:c8","who:mags"],"key":"c8e#1","title":"Break-even","play":{"q":"What does break-even mean for a stall?","opts":["Sales have covered the fixed costs","The stall is closing","Prices are cut in half","Every item is sold out"],"after":"Break-even is the line. Below it you are paying to open; above it you are earning."},"route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-q1","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-q2":{"kind":"question","src":"card:c8e#q2","level":8,"topics":["card:c8e","ch:c8","who:mags"],"key":"c8e#2","title":"Break-even","play":{"q":"Rent is 200. Each sale leaves 10. How many sales to break even?","opts":["20","2","200","10"],"after":"200 ÷ 10 = 20. Cover the rent first; profit starts after."},"route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-q2","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-why0":{"kind":"why","src":"card:c8e#why0","level":8,"topics":["card:c8e","ch:c8","who:mags"],"card":"c8e","title":"Break-even","body":"300 ÷ 15 = 20. The twenty-first sale is the first one that is profit.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-why0","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-why1":{"kind":"why","src":"card:c8e#why1","level":8,"topics":["card:c8e","ch:c8","who:mags"],"card":"c8e","title":"Break-even","body":"Break-even is the line. Below it you are paying to open; above it you are earning.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-why1","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8e-why2":{"kind":"why","src":"card:c8e#why2","level":8,"topics":["card:c8e","ch:c8","who:mags"],"card":"c8e","title":"Break-even","body":"200 ÷ 10 = 20. Cover the rent first; profit starts after.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8e-why2","bands":["sprout","builder"],"grp":"card:c8e"},"f-item-c8e":{"kind":"yourturn","src":"item:c8e","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Your turn","body":"Find the line\nFirst find what one sale leaves after its own cost. Then see how many of those cover the rent.","route":"#/atlas/c8e","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Break-even · with Mags","id":"f-item-c8e","bands":["sprout","builder"],"grp":"card:c8e"},"f-tryit-c8e":{"kind":"tryit","src":"tryit:c8e","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Try it","body":"Find the break-even","route":"#/atlas/c8e","cta":"Change the numbers","maths":"M8","source":"Chapter 8 · Running something · Break-even · with Mags","id":"f-tryit-c8e","bands":["sprout","builder"],"grp":"card:c8e"},"f-card-c8f-teach":{"kind":"lesson","src":"card:c8f#teach","level":8,"topics":["card:c8f","ch:c8","who:nana"],"title":"Customers who come back","body":"Finding a new customer takes effort every time. A customer who comes back costs almost nothing to keep. Fair prices and honest service are how a small shop grows.","route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","card":"c8f","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-teach","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-eg":{"kind":"example","src":"card:c8f#eg","level":8,"topics":["card:c8f","ch:c8","who:nana"],"title":"Customers who come back","body":"Nana's best customers have bought from her for twenty years. She never once tricked them.","route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-eg","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-q0":{"kind":"question","src":"card:c8f#q0","level":8,"topics":["card:c8f","ch:c8","who:nana"],"key":"c8f#0","title":"Running something","play":{"q":"Which usually helps a small shop most over a year?","opts":["Customers who keep coming back","One very big sale","Raising prices on regulars","A sign that says LAST DAY every day"],"after":"Regulars come back by themselves. Tricks win a sale and lose the customer."},"route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-q0","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-q1":{"kind":"question","src":"card:c8f#q1","level":8,"topics":["card:c8f","ch:c8","who:nana"],"key":"c8f#1","title":"Customers who come back","play":{"q":"Why does a regular customer matter so much to a small stall?","opts":["They return without new effort","They pay double","They never complain","They bring their own stock"],"after":"A returning customer is a sale you did not have to win again."},"route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-q1","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-q2":{"kind":"question","src":"card:c8f#q2","level":8,"topics":["card:c8f","ch:c8","who:nana"],"key":"c8f#2","title":"Running something","play":{"q":"A seller tricks a customer into an overpriced buy. What usually happens next?","opts":["The customer does not come back","Nothing at all","The customer tells everyone it was great","The seller gets more regulars"],"after":"One sale won, one customer lost — usually for good."},"route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-q2","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-why0":{"kind":"why","src":"card:c8f#why0","level":8,"topics":["card:c8f","ch:c8","who:nana"],"card":"c8f","title":"Customers who come back","body":"Regulars come back by themselves. Tricks win a sale and lose the customer.","route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-why0","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-why1":{"kind":"why","src":"card:c8f#why1","level":8,"topics":["card:c8f","ch:c8","who:nana"],"card":"c8f","title":"Customers who come back","body":"A returning customer is a sale you did not have to win again.","route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-why1","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8f-why2":{"kind":"why","src":"card:c8f#why2","level":8,"topics":["card:c8f","ch:c8","who:nana"],"card":"c8f","title":"Customers who come back","body":"One sale won, one customer lost — usually for good.","route":"#/atlas/c8f","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8f-why2","bands":["sprout","builder"],"grp":"card:c8f"},"f-item-c8f":{"kind":"yourturn","src":"item:c8f","level":8,"topics":["card:c8f","ch:c8","who:nana"],"title":"Your turn","body":"Brings them back, or loses them?\nTricks win one sale and lose the customer. What kept Nana’s regulars for twenty years?","route":"#/atlas/c8f","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Customers who come back · with Nana Bizz","id":"f-item-c8f","bands":["sprout","builder"],"grp":"card:c8f"},"f-card-c8g-teach":{"kind":"lesson","src":"card:c8g#teach","level":8,"topics":["card:c8g","ch:c8","who:mags"],"title":"Stock that sits","body":"Stock you have not sold is money stuck on a shelf. It cannot pay rent, and some of it goes stale. Buy what sells, and watch what does not.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","card":"c8g","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-teach","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-eg":{"kind":"example","src":"card:c8g#eg","level":8,"topics":["card:c8g","ch:c8","who:mags"],"title":"Stock that sits","body":"Mags bought fifty umbrellas in a dry month. Her money sat in a cupboard until the rain came.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-eg","bands":["builder"],"grp":"card:c8g"},"f-card-c8g-q0":{"kind":"question","src":"card:c8g#q0","level":8,"topics":["card:c8g","ch:c8","who:mags"],"key":"c8g#0","title":"Stock that sits","play":{"q":"A shop has lots of stock but cannot pay the rent. What went wrong?","opts":["Its money is stuck in unsold stock","Rent is always unfair","It sold too much","It has too many customers"],"after":"Stock is money in a different shape. If it does not sell, it cannot pay anything."},"route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-q0","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-q1":{"kind":"question","src":"card:c8g#q1","level":8,"topics":["card:c8g","ch:c8","who:mags"],"key":"c8g#1","title":"Stock that sits","play":{"q":"Why is a full cupboard of unsold stock a worry?","opts":["The money is stuck until it sells","Stock always gets more valuable","Cupboards are expensive","It means business is booming"],"after":"Money on a shelf cannot pay a bill. Some of it may go stale before it sells."},"route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-q1","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-q2":{"kind":"question","src":"card:c8g#q2","level":8,"topics":["card:c8g","ch:c8","who:mags"],"key":"c8g#2","title":"Stock that sits","play":{"q":"What is the smart way to buy stock?","opts":["Buy what you know sells, a bit at a time","Buy whatever is cheapest that day","Buy only what you like","Buy as much as you can afford"],"after":"Buy what moves, and watch what sits. That keeps money flowing."},"route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-q2","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-why0":{"kind":"why","src":"card:c8g#why0","level":8,"topics":["card:c8g","ch:c8","who:mags"],"card":"c8g","title":"Stock that sits","body":"Stock is money in a different shape. If it does not sell, it cannot pay anything.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-why0","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-why1":{"kind":"why","src":"card:c8g#why1","level":8,"topics":["card:c8g","ch:c8","who:mags"],"card":"c8g","title":"Stock that sits","body":"Money on a shelf cannot pay a bill. Some of it may go stale before it sells.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-why1","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8g-why2":{"kind":"why","src":"card:c8g#why2","level":8,"topics":["card:c8g","ch:c8","who:mags"],"card":"c8g","title":"Stock that sits","body":"Buy what moves, and watch what sits. That keeps money flowing.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-card-c8g-why2","bands":["sprout","builder"],"grp":"card:c8g"},"f-item-c8g":{"kind":"yourturn","src":"item:c8g","level":8,"topics":["card:c8g","ch:c8","who:mags"],"title":"Your turn","body":"Can it pay the rent?\nStock is money in a different shape. Until it sells, it cannot pay anything.","route":"#/atlas/c8g","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Stock that sits · with Mags","id":"f-item-c8g","bands":["sprout","builder"],"grp":"card:c8g"},"f-card-c8h-teach":{"kind":"lesson","src":"card:c8h#teach","level":8,"topics":["card:c8h","ch:c8","who:nana"],"title":"Paying yourself","body":"Not all profit is yours to spend. Some must stay in the shop for next week's stock and the quiet weeks. Owners split profit, just like jars split a wage.","route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","card":"c8h","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-teach","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-eg":{"kind":"example","src":"card:c8h#eg","level":8,"topics":["card:c8h","ch:c8","who:nana"],"title":"Paying yourself","body":"Nana keeps half her profit in the shop tin and takes half home. The shop never runs dry.","route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-eg","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-q0":{"kind":"question","src":"card:c8h#q0","level":8,"topics":["card:c8h","ch:c8","who:nana"],"key":"c8h#0","title":"Paying yourself","play":{"q":"Your stall made a good profit this week. What is the wise thing to do with it?","opts":["Keep some in the stall for next week","Take it all home","Give it all to the landlord","Spend it on decorations"],"after":"Next week's stock is paid from this week's profit. Take it all and the stall starts empty."},"route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-q0","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-q1":{"kind":"question","src":"card:c8h#q1","level":8,"topics":["card:c8h","ch:c8","who:nana"],"key":"c8h#1","title":"Paying yourself","play":{"q":"Why does a shop keep some profit back instead of spending it all?","opts":["To pay for next week's stock and quiet weeks","Because profit is not real money","The landlord takes it later","To make the shop look poor"],"after":"Profit kept in the shop is next week's stock and the cushion for a quiet week."},"route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-q1","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-q2":{"kind":"question","src":"card:c8h#q2","level":8,"topics":["card:c8h","ch:c8","who:nana"],"key":"c8h#2","title":"Paying yourself","play":{"q":"How is splitting profit like the four jars?","opts":["Both split money the moment it arrives","Both are only for grown-ups","Neither needs a plan","Both spend everything at once"],"after":"Decide the split first, then live inside it — for a wage or for a shop."},"route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-q2","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-why0":{"kind":"why","src":"card:c8h#why0","level":8,"topics":["card:c8h","ch:c8","who:nana"],"card":"c8h","title":"Paying yourself","body":"Next week's stock is paid from this week's profit. Take it all and the stall starts empty.","route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-why0","bands":["sprout","builder"],"grp":"card:c8h"},"f-card-c8h-why2":{"kind":"why","src":"card:c8h#why2","level":8,"topics":["card:c8h","ch:c8","who:nana"],"card":"c8h","title":"Paying yourself","body":"Decide the split first, then live inside it — for a wage or for a shop.","route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-card-c8h-why2","bands":["sprout","builder"],"grp":"card:c8h"},"f-item-c8h":{"kind":"yourturn","src":"item:c8h","level":8,"topics":["card:c8h","ch:c8","who:nana"],"title":"Your turn","body":"Half stays in the shop\nHalf means two equal piles: one for the tin, one for home.","route":"#/atlas/c8h","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Paying yourself · with Nana Bizz","id":"f-item-c8h","bands":["sprout","builder"],"grp":"card:c8h"},"f-chapter-c8":{"kind":"chapter","src":"chapter:c8","level":8,"topics":["ch:c8"],"title":"Running something","body":"Revenue, cost, profit — and the week you learn those are three different words.","route":"#/atlas/chapter/c8","cta":"The Money Atlas","maths":"M8","source":"Chapter 8 of 8 · 10 lessons on the Money Atlas","id":"f-chapter-c8","bands":["sprout","builder"],"grp":"chapter:c8"},"f-goal-earn-7":{"kind":"goal","src":"goal:EARN-7","level":8,"topics":["card:c8c","ch:c8"],"title":"The till is not your pocket","body":"Keeps the money a business took separate from the money they paid themselves, and says which is which.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · what the lesson is for","id":"f-goal-earn-7","bands":["sprout","builder"],"grp":"card:c8c"},"f-word-revenue":{"kind":"word","src":"word:Revenue","level":8,"topics":["word","word:Revenue","ch:c8"],"title":"Revenue","body":"Everything a business takes in.","route":"#/words/Revenue","cta":"Money Words","source":"Money Words · first used in Chapter 8 · Running something","id":"f-word-revenue","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 8 · Running something","grp":"word:Revenue"},"f-figure-stock":{"kind":"figure","src":"figure:stock","level":8,"topics":["figure","ch:c8"],"badge":{"id":"own","label":"A dial of this town"},"title":"What Bizz & Co's stock costs and sells for","body":"the town's own prices\nChai, umbrellas, ice golas and rope at prices chosen so a stall in the town can make a profit or a loss you can see. They are Bizzington's, not any real market's.","route":"#/sources/stock","cta":"How we know","source":"How we know","id":"f-figure-stock","bands":["sprout","builder"],"maths":"M1","because":"A number Chapter 8 · Running something runs on, and how we know it","grp":"figure:stock"},"f-quest-q-shop":{"kind":"quest","src":"quest:q-shop","level":8,"topics":["quest","ch:c8"],"gate":{"chapter":"c8"},"title":"Trade a day at Bizz & Co","body":"Open the doors and count it honestly.","route":"#/town/today","cta":"Today's three","source":"Today's three · on the town page","id":"f-quest-q-shop","bands":["sprout","builder"],"maths":"M1","because":"One of today’s three, on the town page","grp":"quest:q-shop"},"f-badge-chapter-c8":{"kind":"medal","src":"badge:chapter-c8","level":8,"topics":["medal","ch:c8"],"badgeId":"chapter-c8","title":"Running something","body":"Chapter eight, done.","route":"#/medals/chapter-c8","cta":"How to earn it","source":"Medal · for finishing Chapter 8 · Running something","id":"f-badge-chapter-c8","bands":["sprout","builder"],"maths":"M1","because":"A medal you have not earned yet","grp":"badge:chapter-c8"},"f-stock-chai":{"kind":"shopstock","src":"stock:chai","level":8,"topics":["ch:c8","business"],"gate":{"chapter":"c8"},"title":"Chai","body":"Sells all year. Sells twice as well when it is cold.","route":"#/money/business/chai","cta":"Bizz & Co","source":"Bizz & Co · Chapter 8 · Running something","id":"f-stock-chai","bands":["sprout","builder"],"maths":"M1","because":"Opened by Chapter 8 · Running something","grp":"stock:chai"},"f-stock-umbrella":{"kind":"shopstock","src":"stock:umbrella","level":8,"topics":["ch:c8","business"],"gate":{"chapter":"c8"},"title":"Umbrellas","body":"Enormous margin, and only if it rains.","route":"#/money/business/umbrella","cta":"Bizz & Co","source":"Bizz & Co · Chapter 8 · Running something","id":"f-stock-umbrella","bands":["sprout","builder"],"maths":"M1","because":"Opened by Chapter 8 · Running something","grp":"stock:umbrella"},"f-stock-ice":{"kind":"shopstock","src":"stock:ice","level":8,"topics":["ch:c8","business"],"gate":{"chapter":"c8"},"title":"Ice golas","body":"Melts. Literally a deadline.","route":"#/money/business/ice","cta":"Bizz & Co","source":"Bizz & Co · Chapter 8 · Running something","id":"f-stock-ice","bands":["sprout","builder"],"maths":"M1","because":"Opened by Chapter 8 · Running something","grp":"stock:ice"},"f-stock-rope":{"kind":"shopstock","src":"stock:rope","level":8,"topics":["ch:c8","business"],"gate":{"chapter":"c8"},"title":"Rope & twine","body":"Nobody is excited. Somebody always needs it.","route":"#/money/business/rope","cta":"Bizz & Co","source":"Bizz & Co · Chapter 8 · Running something","id":"f-stock-rope","bands":["sprout","builder"],"maths":"M1","because":"Opened by Chapter 8 · Running something","grp":"stock:rope"},"f-world-works":{"kind":"place","src":"world:works","level":8,"topics":["world:works","ch:c8"],"gate":{"world":4},"title":"The Works","body":"Where things get made, priced, and sold for more than they cost. Or not.\nBizz & Co, and the shutters come off for good.","route":"#/town/works","cta":"The town","source":"Place 5 of 5 in Bizzington","id":"f-world-works","bands":["sprout","builder"],"maths":"M1","grp":"world:works"},"f-fix-kiln":{"kind":"fix","src":"fix:kiln","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The cold kiln","body":"Out. Everything has to be bought in, at somebody else’s price.","route":"#/town/fix/kiln","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-kiln","bands":["sprout","builder"],"maths":"M1","grp":"fix:kiln"},"f-fix-kiln-fixed":{"kind":"fixed","src":"fix:kiln#fixed","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The cold kiln","body":"Lit. You can make instead of buy.\nStock costs you less to make than to buy.","route":"#/town/fix/kiln","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-kiln-fixed","bands":["sprout","builder"],"maths":"M1","grp":"fix:kiln"},"f-fix-sign":{"kind":"fix","src":"fix:sign","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The shop sign","body":"Fallen. People walk past because they do not know you are there.","route":"#/town/fix/sign","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-sign","bands":["sprout","builder"],"maths":"M1","grp":"fix:sign"},"f-fix-sign-fixed":{"kind":"fixed","src":"fix:sign#fixed","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The shop sign","body":"Up, painted, and visible from the corner.\nMore customers every trading day.","route":"#/town/fix/sign","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-sign-fixed","bands":["sprout","builder"],"maths":"M1","grp":"fix:sign"},"f-fix-cart":{"kind":"fix","src":"fix:cart","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The delivery cart","body":"A wheel off. Everything is carried.","route":"#/town/fix/cart","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-cart","bands":["sprout","builder"],"maths":"M1","grp":"fix:cart"},"f-fix-cart-fixed":{"kind":"fixed","src":"fix:cart#fixed","level":8,"topics":["world:works","fix","ch:c8"],"gate":{"world":4},"title":"The delivery cart","body":"Rolling. You can sell further than you can walk.\nMore customers again.","route":"#/town/fix/cart","cta":"Put it right","source":"Put it right · The Works","id":"f-fix-cart-fixed","bands":["sprout","builder"],"maths":"M1","grp":"fix:cart"},"f-assess-earn-7-0":{"kind":"question","src":"assess:EARN-7#0","level":8,"topics":["card:c8c","ch:c8","goal:EARN-7","who:pip"],"key":"EARN-7#0#0","title":"The till is not your pocket","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","play":{"q":"Your stall took 900 this week. How much of that is yours?","opts":["Whatever is left after what it cost to run","Half","None of it","900"],"after":"Money through the till is not money earned. Stock, rent and what spoiled all come out first, and what is left is the part that was ever yours."},"source":"Chapter 8 · Running something · a question to come back to","id":"f-assess-earn-7-0","bands":["sprout","builder"],"grp":"card:c8c"},"f-assess-earn-7-0why":{"kind":"why","src":"assess:EARN-7#0why","level":8,"topics":["card:c8c","ch:c8","goal:EARN-7","who:pip"],"card":"c8c","title":"The till is not your pocket","body":"Money through the till is not money earned. Stock, rent and what spoiled all come out first, and what is left is the part that was ever yours.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · why, said again","id":"f-assess-earn-7-0why","bands":["sprout","builder"],"grp":"card:c8c"},"f-assess-earn-7-2":{"kind":"question","src":"assess:EARN-7#2","level":8,"topics":["card:c8c","ch:c8","goal:EARN-7","who:pip"],"key":"EARN-7#2#0","title":"The till is not your pocket","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","play":{"q":"You take 200 out of the till for yourself. What happened to the business?","opts":["It has 200 less to buy stock with","It is now worth more","Nothing","It made 200 less"],"after":"Drawing money out is not a cost and it is not a loss — but the stall now has less to work with, and next week will show it."},"source":"Chapter 8 · Running something · a question to come back to","id":"f-assess-earn-7-2","bands":["sprout","builder"],"grp":"card:c8c"},"f-assess-earn-7-2why":{"kind":"why","src":"assess:EARN-7#2why","level":8,"topics":["card:c8c","ch:c8","goal:EARN-7","who:pip"],"card":"c8c","title":"The till is not your pocket","body":"Drawing money out is not a cost and it is not a loss — but the stall now has less to work with, and next week will show it.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · why, said again","id":"f-assess-earn-7-2why","bands":["sprout","builder"],"grp":"card:c8c"},"f-sprout-c8c-teach":{"kind":"lesson","src":"sprout:c8c#teach","level":8,"topics":["card:c8c","ch:c8","who:pip"],"bands":["sprout"],"title":"Cash is not profit","body":"You can make a profit and still run out of cash. Profit is a month on paper. Cash is what is in your hand. And the stock bill needs cash.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","card":"c8c","source":"Chapter 8 · Running something · read for a Sprout","id":"f-sprout-c8c-teach","grp":"card:c8c"},"f-sprout-c8g-eg":{"kind":"example","src":"sprout:c8g#eg","level":8,"topics":["card:c8g","ch:c8","who:mags"],"bands":["sprout"],"title":"Stock that sits","body":"Mags bought fifty umbrellas when it was dry. Her money sat in a cupboard until it rained.","route":"#/atlas/c8g","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · read for a Sprout","id":"f-sprout-c8g-eg","grp":"card:c8g"},"f-worked-c8a":{"kind":"worked","src":"worked:c8a","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Three different words","body":"One umbrella sells for 20. Each one cost 8.\nRevenue on 40 of them: 40 × 20 = 800.\nProfit on just one: 20 − 8 = 12 — what each sale leaves after its own cost.","route":"#/atlas/c8a","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-worked-c8a","bands":["sprout","builder"],"grp":"card:c8a"},"f-worked-c8b":{"kind":"worked","src":"worked:c8b","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Setting a price","body":"Mags raised buttons from 8 to 12.\nEach button she still sells now brings 12 − 8 = 4 more.\nShe sold two fewer — so the question is whether the extra on the rest beats the ones she lost.","route":"#/atlas/c8b","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-worked-c8b","bands":["sprout","builder"],"grp":"card:c8b"},"f-worked-c8e":{"kind":"worked","src":"worked:c8e","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Break-even","body":"Rent 240 a month. Each umbrella sells for 20 and costs 8.\nEach sale leaves 20 − 8 = 12 towards the rent.\nTen sales: 10 × 12 = 120 of the 240 covered. Still to cover: 240 − 120 = 120 — keep counting in 12s until nothing is left.","route":"#/atlas/c8e","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Mags","id":"f-worked-c8e","bands":["sprout","builder"],"grp":"card:c8e"},"f-worked-c8h":{"kind":"worked","src":"worked:c8h","level":8,"topics":["card:c8h","ch:c8","who:nana"],"title":"Paying yourself","body":"At Bizz & Co an umbrella sells for {c20} and costs the shop {c8}: {c20} − {c8} = {c12} profit on each.\nTen umbrellas: 10 × {c12} = {c120} profit.\nHalf stays in the shop tin: {c120} ÷ 2 = {c60} goes home.","cur":{"INR":"At Bizz & Co an umbrella sells for ₹200 and costs the shop ₹80: ₹200 − ₹80 = ₹120 profit on each.\nTen umbrellas: 10 × ₹120 = ₹1,200 profit.\nHalf stays in the shop tin: ₹1,200 ÷ 2 = ₹600 goes home.","USD":"At Bizz & Co an umbrella sells for $5 and costs the shop $2: $5 − $2 = $3 profit on each.\nTen umbrellas: 10 × $3 = $30 profit.\nHalf stays in the shop tin: $30 ÷ 2 = $15 goes home.","GBP":"At Bizz & Co an umbrella sells for £4 and costs the shop £2: £4 − £2 = £2 profit on each.\nTen umbrellas: 10 × £2 = £20 profit.\nHalf stays in the shop tin: £20 ÷ 2 = £10 goes home.","EUR":"At Bizz & Co an umbrella sells for €5 and costs the shop €2: €5 − €2 = €3 profit on each.\nTen umbrellas: 10 × €3 = €30 profit.\nHalf stays in the shop tin: €30 ÷ 2 = €15 goes home.","AED":"At Bizz & Co an umbrella sells for د.إ20 and costs the shop د.إ8: د.إ20 − د.إ8 = د.إ12 profit on each.\nTen umbrellas: 10 × د.إ12 = د.إ120 profit.\nHalf stays in the shop tin: د.إ120 ÷ 2 = د.إ60 goes home."},"route":"#/atlas/c8h","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · with Nana Bizz","id":"f-worked-c8h","bands":["sprout","builder"],"grp":"card:c8h"},"f-item-c8a-how":{"kind":"showhow","src":"item:c8a#how","level":8,"topics":["card:c8a","ch:c8","who:nana"],"title":"Revenue, cost, profit","body":"Say you sell 10 cups at 6 each, and each cup cost you 2.\nIn: 10 × 6 = 60. Cost: 10 × 2 = 20.\nProfit: 60 − 20 = 40. Now the umbrellas.","route":"#/atlas/c8a","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Three different words · with Nana Bizz","id":"f-item-c8a-how","bands":["sprout","builder"],"grp":"card:c8a"},"f-item-c8b-how":{"kind":"showhow","src":"item:c8b#how","level":8,"topics":["card:c8b","ch:c8","who:mags"],"title":"Fewer sold, more taken","body":"Say you sell 20 kites at 5, then 15 kites at 7.\nTakings each week: 20 × 5 = 100, and 15 × 7 = 105.\nThe gap: 105 − 100 = 5 more. Fewer sold, more taken.","route":"#/atlas/c8b","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Setting a price · with Mags","id":"f-item-c8b-how","bands":["sprout","builder"],"grp":"card:c8b"},"f-item-c8i-how":{"kind":"showhow","src":"item:c8i#how","level":8,"topics":["card:c8i","ch:c8","who:nana"],"title":"What each hour earned","body":"Say you sell 8 cards at 5 each, the paper costs 2 a card, and it took 4 hours.\nIn: 8 × 5 = 40. Paper: 8 × 2 = 16. Profit: 40 − 16 = 24.\nFor each hour: 24 ÷ 4 = 6. Now try the bracelets.","route":"#/atlas/c8i","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Your time is a cost too · with Nana Bizz","id":"f-item-c8i-how","bands":["sprout","builder"],"grp":"card:c8i"},"f-item-c8e-how":{"kind":"showhow","src":"item:c8e#how","level":8,"topics":["card:c8e","ch:c8","who:mags"],"title":"Find the line","body":"Say rent is 100, and each kite sells for 9 and costs 4.\nEach kite leaves 9 − 4 = 5.\n100 ÷ 5 = 20 kites to break even. Every kite after that is profit.","route":"#/atlas/c8e","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Break-even · with Mags","id":"f-item-c8e-how","bands":["sprout","builder"],"grp":"card:c8e"},"f-item-c8h-how":{"kind":"showhow","src":"item:c8h#how","level":8,"topics":["card:c8h","ch:c8","who:nana"],"title":"Half stays in the shop","body":"Say the profit was 60 and you keep half.\nSplit 60 into two equal piles: 30 and 30.\nOne pile stays in the tin, one goes home. Now split your stall’s profit.","route":"#/atlas/c8h","cta":"Have a go","maths":"M8","source":"Chapter 8 · Running something · Paying yourself · with Nana Bizz","id":"f-item-c8h-how","bands":["sprout","builder"],"grp":"card:c8h"},"f-genhow-earn-7-1":{"kind":"showhow","src":"genhow:EARN-7~1","level":8,"topics":["card:c8c","ch:c8","who:pip","goal:EARN-7"],"title":"The till is not your pocket","body":"The till at Mags’s stall holds {c13}. Mags takes {c4} out as pay. How much is left for the stall to buy stock with?\n{c13} − {c4}. Money taken out for yourself is money the stall no longer has — which is why the two are kept apart.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · Show me how","id":"f-genhow-earn-7-1","bands":["sprout","builder"],"grp":"card:c8c"},"f-genhow-earn-7-6":{"kind":"showhow","src":"genhow:EARN-7~6","level":8,"topics":["card:c8c","ch:c8","who:pip","goal:EARN-7"],"title":"The till is not your pocket","body":"Mags’s stall took {c15} this week. Stock cost {c3} and the pitch cost {c3}. How much of the takings is really Mags’s?\n{c15} − {c3} − {c3}. The till holds the business’s money; only what is left after running it is yours to pay yourself.","route":"#/atlas/c8c","cta":"Open the lesson","maths":"M8","source":"Chapter 8 · Running something · Show me how","id":"f-genhow-earn-7-6","bands":["sprout","builder"],"grp":"card:c8c"},"f-story-works-p0":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p0","body":"Nana Bizz handed Pip the key to the old shop at the Works. “Make chai and sell it,” she said. “Then come and tell me three words: revenue, cost and profit.”","source":"A story · The Works","id":"f-story-works-p0","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-story-works-p1":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p1","body":"On the first day Pip sold cup after cup and took in {200}. That was the revenue: everything that came in.","source":"A story · The Works","id":"f-story-works-p1","bands":["sprout","builder"],"maths":"M3","because":"A story from The Works","grp":"story:works"},"f-story-works-p2":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p2","body":"But Pip’s tea, milk and cups had cost {120}, and the rent for the day was {60}. Take those away and {20} was left, and that was the profit.","source":"A story · The Works","id":"f-story-works-p2","bands":["sprout","builder"],"maths":"M3","because":"A story from The Works","grp":"story:works"},"f-story-works-p3":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p3","body":"“Too cheap and you sell out but earn nothing,” said Mags. “Too dear and you carry it home.” Pip tried a little more per cup, and most people still happily paid.","source":"A story · The Works","id":"f-story-works-p3","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-story-works-p4":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p4","body":"On Friday the tea seller’s bill arrived before the customers did. The week had made a profit on paper, but Pip’s cash tin was nearly empty.","source":"A story · The Works","id":"f-story-works-p4","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-story-works-p5":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p5","body":"“Profit is the week on paper, and cash is what is in your hand when the bill is due,” said Nana. “Keep some profit in the shop for weeks like this, the way jars split a wage.”","source":"A story · The Works","id":"f-story-works-p5","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-story-works-p6":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#p6","body":"So Pip kept a little back every week and was fair to every customer. The same faces came back again and again, and a customer who comes back is the best kind.","source":"A story · The Works","id":"f-story-works-p6","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-story-works-learned":{"kind":"story","level":8,"topics":["world:works","story","ch:c8"],"title":"Three Different Words","route":"#/story/works","cta":"Read the story","src":"story:works#learned","body":"Revenue, cost and profit are three different words, and cash is not profit.","source":"A story · The Works","id":"f-story-works-learned","bands":["sprout","builder"],"maths":"M1","because":"A story from The Works","grp":"story:works"},"f-word-revenue-use":{"kind":"worduse","src":"word:Revenue#use","level":8,"topics":["word","word:Revenue","ch:c8"],"title":"Revenue","route":"#/words/Revenue","cta":"Money Words","source":"Money Words · first used in Chapter 8 · Running something","id":"f-word-revenue-use","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 8 · Running something","grp":"word:Revenue"}};
